'use strict';
const refineState={active:false,contour:null,nodes:[],reverse:false,history:[],result:null};
function refineReset(){refineState.contour=null;refineState.nodes=[];refineState.history=[];refineState.result=null;refineState.active=false;refineRender();}
function refineD(segments){if(!segments.length)return '';return 'M '+segments[0].x1+' '+segments[0].y1+' '+segments.map(s=>s.type==='C'?`C ${s.x2} ${s.y2} ${s.x3} ${s.y3} ${s.x4} ${s.y4}`:s.type==='Q'?`Q ${s.x2} ${s.y2} ${s.x3} ${s.y3}`:`L ${s.x2} ${s.y2}`).join(' ');}
function refineNodes(path){const nodes=path.segments.slice();if(path.open&&nodes.length){const s=nodes[nodes.length-1];nodes.push({x1:s.type==='C'?s.x4:s.type==='Q'?s.x3:s.x2,y1:s.type==='C'?s.y4:s.type==='Q'?s.y3:s.y2});}return nodes;}
function refineArc(){const path=refineState.contour;if(!path||refineState.nodes.length!==2)return null;const n=path.segments.length;let [a,b]=refineState.nodes;if(path.open){[a,b]=[a,b].sort((x,y)=>x-y);return {a,b,count:b-a,segments:path.segments.slice(a,b)};}if(refineState.reverse)[a,b]=[b,a];const count=(b-a+n)%n;return {a,b,count,segments:Array.from({length:count},(_,i)=>path.segments[(a+i)%n])};}
function refineElement(tag,attrs){const el=document.createElementNS('http://www.w3.org/2000/svg',tag);Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,v));return el;}
function refineRender(){const overlay=$('refineOverlay');if(!overlay)return;if(typeof geometrySync==='function')geometrySync();$('refineBtn').disabled=!result;$('refineBtn').setAttribute('aria-pressed',String(refineState.active));$('refineUndo').disabled=!result||!refineState.history.length;$('straightenBtn').disabled=!result||refineState.nodes.length!==2;$('refineOther').disabled=$('straightenBtn').disabled||!!refineState.contour?.open;$('refineClear').disabled=!refineState.contour;overlay.replaceChildren();overlay.toggleAttribute('hidden',!result||!refineState.active||!['wire','path'].includes(view));if(overlay.hasAttribute('hidden')){$('refineHelp').textContent='Aktifkan Refine untuk memilih bagian kontur.';return;}
overlay.setAttribute('viewBox',`0 0 ${result.td.width} ${result.td.height}`);overlay.setAttribute('preserveAspectRatio','none');const scale=result.td.width/Math.max(1,$('artboard').clientWidth);let ordinal=0;(result.td.graph?[result.td.graph.edges]:result.td.layers).forEach((layer,li)=>{if(!result.td.graph&&result.td.palette[li].a===0)return;layer.forEach(path=>{if(result.td.graph&&![path.left,path.right].some(id=>id>=0&&result.td.palette[result.td.graph.faces[id].color].a>0))return;ordinal++;if(!path.segments.length)return;const el=refineElement('path',{d:refineD(path.segments)+(path.open?'':' Z'),class:'refine-hit',tabindex:0,role:'button','aria-label':(result.td.graph?'Pilih batas bersama ':'Pilih kontur ')+ordinal});const select=()=>{refineState.contour=path;refineState.nodes=[];refineRender();};el.onclick=e=>{e.stopPropagation();select();};el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select();}};overlay.append(el);});});
const path=refineState.contour;if(!path){$('refineHelp').textContent=result.td.graph?'1. Klik batas. Edit akan mengikuti kedua bidang; titik pertemuan dikunci.':'1. Klik garis kontur yang ingin diperbaiki.';return;}overlay.append(refineElement('path',{d:refineD(path.segments)+(path.open?'':' Z'),class:'refine-selected'}));const arc=refineArc();if(arc){overlay.append(refineElement('path',{d:refineD(arc.segments),class:'refine-arc'}));const nodes=refineNodes(path),a=nodes[arc.a],b=nodes[arc.b];overlay.append(refineElement('path',{d:`M ${a.x1} ${a.y1} L ${b.x1} ${b.y1}`,class:'refine-proposal'}));$('refineHelp').textContent=`${arc.count} segmen terpilih → 1 garis / 2 node ujung. Garis putus-putus menunjukkan hasil.`;}else $('refineHelp').textContent='2. Klik node awal dan akhir. Node di antaranya akan diganti.';
if(typeof geometryDraw==='function')geometryDraw(overlay);refineNodes(path).forEach((s,i)=>{const selected=refineState.nodes.includes(i);const node=refineElement('circle',{cx:s.x1,cy:s.y1,r:(selected?5.5:4)*scale,class:'refine-node'+(selected?' chosen':''),tabindex:0,role:'button','aria-label':'Node '+(i+1),'aria-pressed':String(selected)});const choose=()=>{if(refineState.nodes.includes(i))refineState.nodes=refineState.nodes.filter(v=>v!==i);else{if(refineState.nodes.length===2)refineState.nodes=[];refineState.nodes.push(i);}refineState.reverse=false;if(refineState.nodes.length===2&&!path.open){const [a,b]=refineState.nodes;refineState.reverse=(b-a+path.segments.length)%path.segments.length>path.segments.length/2;}refineRender();};node.onclick=e=>{e.stopPropagation();choose();};node.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose();}};overlay.append(node);});}
function refineUpdate(){if(result.td.graph){VectorGraph.sync(result.td);VectorGraph.validate(result.td);}result.stats=PreciseEngine.stats(result.td);result.smart=null;if(result.analysis.refinement)result.analysis.refinement={enabled:false};renderResult();setView(preferredView);measureDifference();$('resultStatus').textContent='Diedit manual';$('convertHint').textContent='Edit manual tersimpan di ekspor. Mengubah parameter tracing mengganti edit ini.';}
$('refineBtn').onclick=()=>{if(!result)return;refineState.active=!refineState.active;if(refineState.active&&!['wire','path'].includes(view)){preferredView='wire';setView('wire');}refineRender();};
$('refineOther').onclick=()=>{refineState.reverse=!refineState.reverse;refineRender();};
$('refineClear').onclick=()=>{refineState.contour=null;refineState.nodes=[];refineRender();};
$('straightenBtn').onclick=()=>{const arc=refineArc(),path=refineState.contour;if(!result||!arc||!arc.count)return;const segs=path.segments,n=segs.length,a=refineNodes(path)[arc.a],b=refineNodes(path)[arc.b];const straight={type:'L',x1:a.x1,y1:a.y1,x2:b.x1,y2:b.y1};const remaining=path.open?segs.slice(arc.b):Array.from({length:n-arc.count},(_,i)=>segs[(arc.b+i)%n]);if(Math.hypot(a.x1-b.x1,a.y1-b.y1)<.01||(!path.open&&remaining.length<2&&remaining.every(s=>s.type==='L'))){showToast('Seleksi ini akan membuat kontur kehilangan luas. Pilih bagian yang lebih pendek.');return;}if(!refineCommit(path,path.open?[...segs.slice(0,arc.a),straight,...remaining]:[straight,...remaining]))return;showToast(`${arc.count} segmen diganti satu garis lurus. Kedua node ujung tetap.`);};
$('refineUndo').onclick=()=>{const last=refineState.history.pop();if(!result||!last)return;last.path.segments=last.segments;refineState.contour=last.path;refineState.nodes=[];refineUpdate();if($('geometryStatus'))$('geometryStatus').textContent='Edit terakhir dibatalkan; geometri sebelumnya dipulihkan.';};
refineRender();


function refineCommit(path,segments){const original=path.segments;path.segments=segments;try{if(result.td.graph){VectorGraph.sync(result.td);VectorGraph.validate(result.td);}}catch(e){path.segments=original;if(result.td.graph)VectorGraph.sync(result.td);showToast(e.message);return false;}refineState.history.push({path,segments:structuredClone(original)});if(refineState.history.length>20)refineState.history.shift();refineState.nodes=[];refineUpdate();return true;}
